# Code generated by Claude
"""The world model of the MPVI pipeline: a knowledge base of the objects and fixtures (design plan 8, D4 addendum 2).

    world = WorldModel([SimGroundTruthSource(model, data, task_cfg)])
    world.refresh()                                   # the sources write what they know now
    world.get("beaker").properties["held_by"]         # every module reads objects only through this interface
    world.entries(kind="object")

Each entry (class Entry) is what the paper's knowledge base keeps and a little more: an id, a name and the phrases it answers to, a position (and an up axis) in the world frame,
properties (contents "empty" or "liquid", held_by "left" / "right" / None, hot, ...), how it was found ("map", "sim_ground_truth", later "detector", "operator") and when it was last
seen (sim time). Fixtures come from the lab map (kind "fixture"), the small objects from a source (kind "object").

A SOURCE is a callable source(world, t) that upserts entries. The sim ground-truth source reads the simulator; perception (design plan 13) later is another source that writes the same
entries with found = "detector", and nothing else changes. The scripted modules ask for object poses (object_pose), the navigation stances (stance), the bench height (bench_top_z) and an
object's height (object_height) through this class, never from the simulator directly.

Contents:
    Entry: one entry of the knowledge base.
    WorldModel: the knowledge base.
    SimGroundTruthSource: the source that reads the beaker, the hotplate and the bench from the simulator.
"""

from dataclasses import dataclass, field

import mujoco
import numpy as np

from src.task_beaker_hotplate import bench_top_z
from src.task_config import BEAKER_CFG, TASK_CFG


@dataclass
class Entry:
    """One object or fixture of the knowledge base.

    Attributes:
        id (str): Unique name ("beaker").
        name (str): What it is, for people ("beaker").
        phrases (tuple of str): The noun phrases it answers to ("beaker", "glass beaker"); the grounding matches the plan's phrases against them.
        kind (str): "object" (small, movable) or "fixture" (from the lab map).
        position (numpy.ndarray): (3,) world position: an object's bottom centre, a fixture's top centre (the bench: the stance point on its top).
        axis (numpy.ndarray or None): (3,) the up axis, None if unknown.
        properties (dict): contents ("empty" or "liquid"), held_by (None, "left" or "right"), height, and so on.
        found (str): How it got here: "map", "sim_ground_truth", "detector" or "operator".
        last_seen (float): Sim time of the last update, seconds.
    """

    id: str
    name: str
    phrases: tuple
    kind: str
    position: np.ndarray
    axis: object = None
    properties: dict = field(default_factory=dict)
    found: str = "sim_ground_truth"
    last_seen: float = 0.0

    def words(self):
        """Gives the words that describe this entry: the words of its phrases and its text-valued properties.

        Returns:
            set of str: Lower-case words.
        """
        out = {w for p in self.phrases for w in p.lower().split()}
        out |= {v.lower() for v in self.properties.values() if isinstance(v, str)}
        return out

    def describe(self):
        """Gives a one-line description with the position and the properties, for the operator and the logs.

        Returns:
            str: For example "beaker (object) at (0.70, 1.43, 0.84) m, contents liquid, held_by None".
        """
        props = ", ".join(f"{k} {v}" for k, v in self.properties.items() if k in ("contents", "held_by", "hot"))
        return f"{self.id} ({self.kind}) at ({self.position[0]:.2f}, {self.position[1]:.2f}, {self.position[2]:.2f}) m" + (f", {props}" if props else "")


class WorldModel:
    """The knowledge base. Modules read it; sources write it.

    Attributes:
        sources (list): The sources, called in order by refresh().
        time (float): The sim time of the latest refresh.
    """

    def __init__(self, sources=()):
        """Builds an empty knowledge base.

        Args:
            sources (iterable of callable): Sources source(world, t), called by refresh().
        """
        self.sources = list(sources)
        self.time = 0.0
        self._entries = {}

    def upsert(self, entry):
        """Adds an entry or replaces the one with the same id.

        Args:
            entry (Entry): The entry; its last_seen is the time of the latest refresh unless the source set it.
        """
        self._entries[entry.id] = entry

    def remove(self, entry_id):
        """Removes an entry (an object that is known to be gone). Does nothing if it is not there.

        Args:
            entry_id (str): The entry's id.
        """
        self._entries.pop(entry_id, None)

    def refresh(self, t=None):
        """Lets every source write what it knows now.

        Args:
            t (float or None): Sim time to give the sources. None keeps the time of the previous refresh.
        """
        if t is not None:
            self.time = float(t)
        for src in self.sources:
            src(self, self.time)

    def get(self, entry_id):
        """Gives an entry.

        Args:
            entry_id (str): Its id.

        Returns:
            Entry: The entry.

        Raises:
            KeyError: If the model has no such entry.
        """
        if entry_id not in self._entries:
            raise KeyError(f"the world model has no entry {entry_id!r}")
        return self._entries[entry_id]

    def entries(self, kind=None):
        """Lists the entries.

        Args:
            kind (str or None): "object" or "fixture" to list only those. Defaults to all.

        Returns:
            list[Entry]: The entries, in the order they were first added.
        """
        return [e for e in self._entries.values() if kind is None or e.kind == kind]

    def held_by(self, side):
        """Lists what a hand holds.

        Args:
            side (str): "left" or "right".

        Returns:
            list[Entry]: The entries whose held_by property is that side.
        """
        return [e for e in self._entries.values() if e.properties.get("held_by") == side]

    def object_pose(self, entry_id):
        """Gives an entry's pose as it is now (the sources are refreshed first).

        Args:
            entry_id (str): The entry's id.

        Returns:
            dict: {"position": (3,) copy, "axis": (3,) copy} as the modules use it.
        """
        self.refresh()
        e = self.get(entry_id)
        return {"position": np.array(e.position, float), "axis": None if e.axis is None else np.array(e.axis, float)}

    def object_height(self, entry_id):
        """Gives an object's height from its properties.

        Args:
            entry_id (str): The entry's id.

        Returns:
            float: Metres.
        """
        return float(self.get(entry_id).properties["height"])

    def bench_top_z(self):
        """Gives the height of the bench top (the "bench" fixture's top_z property).

        Returns:
            float: Metres.
        """
        return float(self.get("bench").properties["top_z"])

    def stance(self, target):
        """Gives the staging stance of a navigation target (a fixture with a "stance" property).

        Args:
            target (str): The fixture's id ("bench").

        Returns:
            dict: {"xy", "yaw", "pedestal_q"}.

        Raises:
            KeyError: If there is no such fixture or it has no stance.
        """
        e = self._entries.get(target)
        if e is None or "stance" not in e.properties:
            raise KeyError(f"the world model has no navigation target {target!r}")
        return e.properties["stance"]


class SimGroundTruthSource:
    """The source that reads the task scene from the simulator: the beaker (object), the hotplate and the bench (fixtures).

    Replaced by perception later (design plan 13): same entries, found = "detector".
    """

    def __init__(self, model, data, task_cfg=TASK_CFG, beaker_cfg=BEAKER_CFG):
        """Looks the bodies up.

        Args:
            model (mujoco.MjModel): The task model.
            data (mujoco.MjData): The live state, read at every call.
            task_cfg (dict): TASK_CFG, for the staging stance. Defaults to it.
            beaker_cfg (dict): BEAKER_CFG, for the beaker's height and liquid. Defaults to it.
        """
        self.model, self.data, self.task_cfg, self.beaker_cfg = model, data, task_cfg, beaker_cfg
        self.beaker_body = model.body(beaker_cfg["body"]).id
        self.hotplate_body = model.body("task_hotplate").id
        self.beaker_geoms = {g for g in range(model.ngeom) if model.geom_bodyid[g] == self.beaker_body}
        self.fingers = {}
        for side in ("left", "right"):
            ids = []
            for name in ("left_finger_collision", "right_finger_collision"):
                gid = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_GEOM, f"openarm_{side}_{name}")
                ids.append(gid)
            self.fingers[side] = {g for g in ids if g >= 0}

    def held_by(self):
        """Tells which hand holds the beaker: both finger geoms of that hand touch it.

        Returns:
            str or None: "left", "right" or None.
        """
        d = self.data
        touching = {side: set() for side in self.fingers}
        for i in range(d.ncon):
            c = d.contact[i]
            for g_f, g_b in ((c.geom1, c.geom2), (c.geom2, c.geom1)):
                if g_b in self.beaker_geoms:
                    for side, fingers in self.fingers.items():
                        if g_f in fingers:
                            touching[side].add(g_f)
        for side, got in touching.items():
            if self.fingers[side] and got == self.fingers[side]:
                return side
        return None

    def __call__(self, world, t):
        """Writes the beaker, the hotplate and the bench into the world model.

        Args:
            world (WorldModel): The knowledge base to write.
            t (float): The time the world model was last given (unused: this source stamps the entries with the simulator's own clock, data.time).
        """
        m, d, cfg = self.model, self.data, self.task_cfg
        t = float(d.time)
        world.time = t
        top_z = bench_top_z(m)
        world.upsert(Entry("beaker", "beaker", ("beaker", "glass beaker"), "object", d.site("beaker_base").xpos.copy(),
                           d.xmat[self.beaker_body].reshape(3, 3)[:, 2].copy(),
                           {"contents": "liquid" if self.beaker_cfg["liquid_mass"] > 0 else "empty", "height": self.beaker_cfg["height"], "held_by": self.held_by()},
                           "sim_ground_truth", t))
        world.upsert(Entry("hotplate", "hotplate", ("hotplate", "hot plate"), "fixture", d.site("hotplate_top").xpos.copy(),
                           d.xmat[self.hotplate_body].reshape(3, 3)[:, 2].copy(), {}, "map", t))
        xy = cfg["staging_xy"]
        world.upsert(Entry("bench", "bench", ("bench", "lab bench"), "fixture", np.array([xy[0], xy[1], top_z]), None,
                           {"top_z": top_z, "stance": {"xy": cfg["staging_xy"], "yaw": cfg["staging_yaw"], "pedestal_q": cfg["pedestal_q"]}}, "map", t))
